cases.good:
// Post-build patch: replace with explicit closure factory
(function(e, t) {
  var fn = function() { "use strict"; return t.apply(this, arguments); };
  Object.defineProperty(fn, "name", { value: e, configurable: true });
  return fn;
})(e, t);
// → No eval, CSP-compliant, same behavior

